import{_ as a,o as t,c as s,a4 as c}from"./chunks/framework.DA9C4Pbl.js";const b=JSON.parse('{"title":"arcsecond webcam","description":"","frontmatter":{"title":"arcsecond webcam","visibility":"public","audience":"operator","tier":"reference","source":"generated","cli":"4.2.1"},"headers":[],"relativePath":"reference/commands/webcam.md","filePath":"reference/commands/webcam.md"}'),o={name:"reference/commands/webcam.md"};function r(d,e,i,n,h,l){return t(),s("div",null,[...e[0]||(e[0]=[c('<h1 id="arcsecond-webcam" tabindex="-1"><code>arcsecond webcam</code> <a class="header-anchor" href="#arcsecond-webcam" aria-label="Permalink to “arcsecond webcam”">​</a></h1><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>arcsecond webcam [OPTIONS] [COMMAND] [ARGS]...</span></span></code></pre></div><p>List your webcams — plugged into this machine, or reached over the network.</p><p>With no sub-command, prints what is registered and probes nothing. Use <code>detect</code> to look at the hardware, <code>add</code> to register a camera and <code>forget</code> to drop one.</p><p><strong>Subcommands</strong></p><ul><li><a href="#arcsecond-webcam-add"><code>arcsecond webcam add</code></a> — Register a webcam, so that the proxy serves it.</li><li><a href="#arcsecond-webcam-detect"><code>arcsecond webcam detect</code></a> — Look for webcams and report how they line up with what is registered: newly detected, registered and present,...</li><li><a href="#arcsecond-webcam-forget"><code>arcsecond webcam forget</code></a> — Stop remembering a webcam.</li><li><a href="#arcsecond-webcam-test"><code>arcsecond webcam test</code></a> — Pull one image from a camera and report what came back.</li></ul><h2 id="arcsecond-webcam-add" tabindex="-1"><code>arcsecond webcam add</code> <a class="header-anchor" href="#arcsecond-webcam-add" aria-label="Permalink to “arcsecond webcam add”">​</a></h2><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>arcsecond webcam add [OPTIONS] CAMERA</span></span></code></pre></div><p>Register a webcam, so that the proxy serves it.</p><p>CAMERA is either a device index for a webcam plugged into this machine (<code>0</code>, as printed by <code>detect</code>), or the address of a camera on the network (<code>rtsp://...</code>, <code>http://.../snapshot.jpg</code>). Write a password as ${VARIABLE} to keep it out of your shell history — only the variable name is written to disk.</p><p>Prints the camera&#39;s id. That id is the only handle you need afterwards, and it does not change.</p><p><strong>Arguments</strong></p><ul><li><code>CAMERA</code> — required</li></ul><p><strong>Options</strong></p><table tabindex="0"><thead><tr><th>Option</th><th>Description</th></tr></thead><tbody><tr><td><code>--label TEXT</code></td><td>A name for yourself, e.g. &#39;Dome cam&#39;.</td></tr></tbody></table><h2 id="arcsecond-webcam-detect" tabindex="-1"><code>arcsecond webcam detect</code> <a class="header-anchor" href="#arcsecond-webcam-detect" aria-label="Permalink to “arcsecond webcam detect”">​</a></h2><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>arcsecond webcam detect [OPTIONS]</span></span></code></pre></div><p>Look for webcams and report how they line up with what is registered: newly detected, registered and present, registered but not found.</p><p>Registers nothing. Network cameras cannot be discovered — there is no way to ask a network which of it is a camera — so a registered one is confirmed by connecting to its address instead.</p><p><strong>Options</strong></p><table tabindex="0"><thead><tr><th>Option</th><th>Description</th></tr></thead><tbody><tr><td><code>--timeout FLOAT</code></td><td>Seconds to wait for a network camera to answer. [default: 2.0]</td></tr><tr><td><code>--no-network</code></td><td>Do not contact network cameras; list them without checking.</td></tr></tbody></table><h2 id="arcsecond-webcam-forget" tabindex="-1"><code>arcsecond webcam forget</code> <a class="header-anchor" href="#arcsecond-webcam-forget" aria-label="Permalink to “arcsecond webcam forget”">​</a></h2><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>arcsecond webcam forget [OPTIONS] CAMERA_ID</span></span></code></pre></div><p>Stop remembering a webcam. Give the id printed by <code>arcsecond webcam</code>, e.g. <code>k3f</code>.</p><p>Works for every kind of webcam, whether it is plugged in here or reached over the network. If the proxy is running, it stops serving the camera straight away.</p><p><strong>Arguments</strong></p><ul><li><code>CAMERA_ID</code> — required</li></ul><h2 id="arcsecond-webcam-test" tabindex="-1"><code>arcsecond webcam test</code> <a class="header-anchor" href="#arcsecond-webcam-test" aria-label="Permalink to “arcsecond webcam test”">​</a></h2><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>arcsecond webcam test [OPTIONS] CAMERA</span></span></code></pre></div><p>Pull one image from a camera and report what came back.</p><p>CAMERA is the id of a registered camera, or an address you have not registered yet — so an address can be checked before it is added, and a registered camera can be checked without retyping its address.</p><p><strong>Arguments</strong></p><ul><li><code>CAMERA</code> — required</li></ul><p><strong>Options</strong></p><table tabindex="0"><thead><tr><th>Option</th><th>Description</th></tr></thead><tbody><tr><td><code>--timeout FLOAT</code></td><td>Seconds to wait for a first image. [default: 15.0]</td></tr></tbody></table>',35)])])}const g=a(o,[["render",r]]);export{b as __pageData,g as default};
